/* delc-kit.js — the shared look for every delcAPP (logo, colors, fonts, wordmark, app icon, print letterhead).
   Lives on the DELC Apps Hub: https://delcdata.github.io/DELCAppsHub/delc-kit.js
   Each app loads it with one <script> tag. Change the logo or a color here and every app follows.
   Apps must still work if this file fails to load, so they check `window.DELC` before using it.
   v3 · 2026-11-14 (v2: shared header buttons .delc-hbtn; v3: no gold — navy, gray, green wordmark; raspberry accent only for categories) */
(function () {
  if (window.DELC) return;
  var LOGO = 'data:image/png;base64,';
  var LOGO_SQ = 'data:image/png;base64,';
  var TOUCH = 'data:image/png;base64,';
  var CHURCH = 'Duncansville Evangelical Lutheran Church';
  var HUB = 'https://delcdata.github.io/DELCAppsHub/';

  /* letterhead + footer used on every printed document (also handed to pop-up print windows as DELC.printCss) */
  var PRINT_CSS =
    '.delc-lh{display:flex;align-items:center;gap:16px;padding-bottom:10px;border-bottom:3px solid #1B3254;margin-bottom:14px;-webkit-print-color-adjust:exact;print-color-adjust:exact;font-family:"Figtree","Segoe UI",Helvetica,Arial,sans-serif;text-align:left}' +
    '.delc-lh img{height:58px;width:auto;flex-shrink:0}' +
    '.delc-lh .lh-main{min-width:0;flex:1}' +
    '.delc-lh .lh-org{font-size:9.5pt;color:#555;font-weight:700;letter-spacing:.02em}' +
    '.delc-lh .lh-title{font-size:17pt;font-weight:800;color:#1B3254;line-height:1.15;margin:1px 0 0}' +
    '.delc-lh .lh-sub{font-size:10.5pt;color:#333;margin-top:3px}' +
    '.delc-lh .lh-right{margin-left:auto;text-align:right;font-size:9.5pt;color:#555;line-height:1.5;flex-shrink:0}' +
    '.delc-lf{margin-top:18px;padding-top:8px;border-top:1px solid #d9dee7;font-size:8pt;color:#666;display:flex;justify-content:space-between;gap:12px;font-family:"Figtree","Segoe UI",Helvetica,Arial,sans-serif}';

  var CSS =
    ':root{--delc-navy:#1B3254;--delc-navy2:#26446f;--delc-navy-d:#14273F;--delc-soft:#e6ecf5;--delc-focus:#2F80ED;--delc-accent:#B83280;--delc-green:#84c225;' +
    '--delc-display:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;--delc-body:"Figtree","Segoe UI",system-ui,-apple-system,sans-serif;' +
    '--delc-bg:#eef1f6;--delc-card:#ffffff;--delc-ink:#18233a;--delc-muted:#5d6a82;--delc-line:#dbe1ea}' +
    /* dark values: an app opts in by putting class="delc-dark-ok" on <html> once its own styles use these tokens */
    '@media (prefers-color-scheme:dark){:root.delc-dark-ok{--delc-bg:#0f1624;--delc-card:#172133;--delc-ink:#e6ebf4;--delc-muted:#9aa7bd;--delc-line:#2a3750;--delc-soft:#22314d}}' +
    '.delc-wm{display:inline-flex;align-items:baseline;font-family:var(--delc-display);font-weight:800;letter-spacing:-.01em;color:#fff;white-space:nowrap}' +
    '.delc-wm b{color:var(--delc-green);font-weight:800}' +
    '.delc-wm.pill{background:var(--delc-navy);border-radius:8px;padding:3px 10px}' +
    '.delc-logo{display:block;width:230px;max-width:80%;height:auto;margin:0 auto 10px}' +
    '.delc-apps{display:inline-flex;align-items:center;gap:5px;color:#fff;background:rgba(255,255,255,.14);border:0;border-radius:8px;padding:6px 11px;font:inherit;font-size:13px;font-weight:700;text-decoration:none;cursor:pointer;white-space:nowrap}' +
    '.delc-apps:hover{background:rgba(255,255,255,.24)}' +
    /* ONE look for every button in an app's navy header (Apps, Sign out, Undo…). .pri = the single main action (+ New, + Event): white. No gold anywhere (2026-11-14). */
    '.delc-hbtn.delc-hbtn{display:inline-flex;align-items:center;justify-content:center;gap:5px;box-sizing:border-box;min-height:32px;margin:0!important;background:rgba(255,255,255,.12)!important;border:0!important;box-shadow:none!important;color:#fff!important;border-radius:8px!important;padding:5px 11px!important;font-family:inherit!important;font-size:13px!important;font-weight:700!important;line-height:1.2!important;letter-spacing:0!important;text-decoration:none!important;text-transform:none!important;white-space:nowrap;cursor:pointer;opacity:1}' +
    '.delc-hbtn.delc-hbtn:hover{background:rgba(255,255,255,.22)!important}' +
    '.delc-hbtn.delc-hbtn.pri{background:#fff!important;color:#1B3254!important}.delc-hbtn.delc-hbtn.pri:hover{background:#e9eef6!important}' +
    '@media(max-width:480px){.delc-hbtn.delc-hbtn{padding:5px 8px!important;min-height:30px}}' + PRINT_CSS;

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]; }); }
  function add(tag, attrs) { try { var el = document.createElement(tag); for (var k in attrs) el.setAttribute(k, attrs[k]); document.head.appendChild(el); return el; } catch (_) { return null; } }

  try { var st = document.createElement('style'); st.id = 'delc-kit-css'; st.textContent = CSS; document.head.appendChild(st); } catch (_) {}
  if (!window.DELC_NO_FONTS) {
    add('link', {rel: 'preconnect', href: 'https://fonts.googleapis.com'});
    add('link', {rel: 'stylesheet', href: 'https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700;12..96,800&family=Figtree:wght@400;500;600;700;800&display=swap'});
  }
  /* the church mark as the browser-tab icon and the phone home-screen icon */
  if (!document.querySelector('link[rel~="icon"]')) add('link', {rel: 'icon', type: 'image/png', href: LOGO_SQ});
  if (!document.querySelector('link[rel="apple-touch-icon"]')) add('link', {rel: 'apple-touch-icon', href: TOUCH});
  if (!document.querySelector('meta[name="theme-color"]')) add('meta', {name: 'theme-color', content: '#1B3254'});

  window.DELC = {
    version: 3, church: CHURCH, hubUrl: HUB, logo: LOGO, logoSquare: LOGO_SQ, printCss: PRINT_CSS, esc: esc,
    colors: {navy: '#1B3254', navy2: '#26446f', navyDark: '#14273F', soft: '#e6ecf5', focus: '#2F80ED', accent: '#B83280', green: '#84c225'},
    /* delcBOARD-style name: DELC.wordmark('EVENTS') on navy, DELC.wordmark('EVENTS', true) as a navy pill on a light card */
    wordmark: function (suffix, pill) { return '<span class="delc-wm' + (pill ? ' pill' : '') + '">delc<b>' + esc(suffix) + '</b></span>'; },
    /* full church logo for sign-in cards */
    logoImg: function (alt) { return '<img class="delc-logo" src="' + LOGO + '" alt="' + esc(alt || CHURCH) + '">'; },
    /* "Apps" button back to the Hub */
    appsLink: function (label) { return '<a class="delc-apps" href="' + HUB + '" title="Back to the DELC Apps Hub">' + esc(label || 'Apps') + '</a>'; },
    /* top of every printed page. title and sub are plain text; right is HTML the app has already made safe. */
    letterhead: function (o) { o = o || {};
      return '<div class="delc-lh"><img src="' + LOGO + '" alt="DELC"><div class="lh-main"><div class="lh-org">' + esc(o.org || CHURCH) + '</div><div class="lh-title">' + esc(o.title || '') + '</div>' +
        (o.sub ? '<div class="lh-sub">' + esc(o.sub) + '</div>' : '') + '</div>' + (o.right ? '<div class="lh-right">' + o.right + '</div>' : '') + '</div>'; },
    /* bottom of every printed page: app name on the left, print date on the right */
    footer: function (appName, extra) { var d = new Date().toLocaleDateString('en-US', {month: 'long', day: 'numeric', year: 'numeric'});
      return '<div class="delc-lf"><span>' + esc(CHURCH) + ' · ' + esc(appName || 'delcAPPS') + (extra ? ' · ' + esc(extra) : '') + '</span><span>Printed ' + esc(d) + '</span></div>'; }
  };
})();
